CREATE TABLE IF NOT EXISTS research_projects (id VARCHAR(64) PRIMARY KEY,institution_id VARCHAR(64) NOT NULL,student_id VARCHAR(64) NOT NULL,academic_registration_id VARCHAR(64) NOT NULL,kind VARCHAR(16) NOT NULL CHECK(kind IN ('tfc','memoire','these')),title VARCHAR(500) NOT NULL,supervisor_account_id VARCHAR(64) NOT NULL,state VARCHAR(32) NOT NULL,version INTEGER NOT NULL DEFAULT 1,created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE INDEX IF NOT EXISTS ix_research_projects_institution_id ON research_projects(institution_id); CREATE INDEX IF NOT EXISTS ix_research_projects_student_id ON research_projects(student_id);
CREATE TABLE IF NOT EXISTS research_revisions (id VARCHAR(64) PRIMARY KEY,project_id VARCHAR(64) NOT NULL REFERENCES research_projects(id),number INTEGER NOT NULL,document_ref VARCHAR(500) NOT NULL,sha256 VARCHAR(64) NOT NULL,state VARCHAR(32) NOT NULL,student_note VARCHAR(2000) NOT NULL DEFAULT '',reviewer_note VARCHAR(3000),created_at TIMESTAMP WITH TIME ZONE NOT NULL,reviewed_at TIMESTAMP WITH TIME ZONE,CONSTRAINT uq_research_revision_number UNIQUE(project_id,number));
CREATE INDEX IF NOT EXISTS ix_research_revisions_project_id ON research_revisions(project_id);
CREATE TABLE IF NOT EXISTS research_defenses (id VARCHAR(64) PRIMARY KEY,project_id VARCHAR(64) NOT NULL UNIQUE REFERENCES research_projects(id),scheduled_at TIMESTAMP WITH TIME ZONE NOT NULL,room VARCHAR(120) NOT NULL,chair_account_id VARCHAR(64) NOT NULL,secretary_account_id VARCHAR(64) NOT NULL,status VARCHAR(24) NOT NULL,decision VARCHAR(24),score FLOAT,minutes_sha256 VARCHAR(64),created_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE INDEX IF NOT EXISTS ix_research_defenses_project_id ON research_defenses(project_id);
